import sys

def main():
    R = int(sys.stdin.readline().strip())

    for i in range(1, R + 1):
        if i == 1:
            print("1")
        elif i == R:
            print(" ".join(str(j) for j in range(1, R + 1)))
        else:
            print("1 " + " ".join(str(k) for k in range(3, i + 1)))

if __name__ == "__main__":
    main()
